import React, { useState } from 'react';
import { User, MapPin, Search, X, FileText, AlertOctagon, Calendar, CreditCard, ChevronRight, Trophy, CheckCircle2, Phone, Fingerprint } from 'lucide-react';

const CitizensTab = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCitizen, setSelectedCitizen] = useState(null);
  const [activeFilter, setActiveFilter] = useState('PROFILE');

  // Directory Data
  const citizens = [
    { id: 'CZ-8821', name: 'ARJUN MEHTA', area: 'GANDHI_NAGAR', zone: 'ZONE_A', status: 'ACTIVE', phone: '+91 98XXX XXXXX' },
    { id: 'CZ-4412', name: 'SARA KHAN', area: 'SILICON_VALLEY', zone: 'ZONE_C', status: 'OVERDUE', phone: '+91 88XXX XXXXX' },
    { id: 'CZ-9003', name: 'VIKRAM SINGH', area: 'OLD_TOWN', zone: 'ZONE_B', status: 'ACTIVE', phone: '+91 77XXX XXXXX' },
  ];

  const closeModal = () => {
    setSelectedCitizen(null);
    setActiveFilter('PROFILE');
  };

  return (
    <div className="w-full h-full flex flex-col gap-6 font-black italic uppercase tracking-tighter select-none">

      {/* 🔍 SEARCH & HEADER RIG */}
      <div className="flex flex-col md:flex-row gap-4 items-center justify-between bg-[#FFF24D] p-6 rounded-[32px] border-4 border-[#47510B] shadow-[8px_8px_0_0_#47510B]">
        <div className="flex items-center gap-4">
          <Fingerprint size={40} />
          <div>
            <h1 className="text-3xl leading-none">CITIZEN_REGISTRY</h1>
            <p className="text-[10px] opacity-50">AUTHORIZED_ACCESS_ONLY // DATABASE_v4.2</p>
          </div>
        </div>
        <div className="relative w-full md:w-96">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-[#47510B]/40" size={20} />
          <input 
            type="text" 
            placeholder="SEARCH_BY_ID_OR_NAME..." 
            className="w-full bg-white border-4 border-[#47510B] rounded-2xl p-4 pl-12 outline-none focus:ring-4 ring-[#CAD23C]/30 transition-all shadow-[4px_4px_0_0_#47510B]"
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      {/* 📋 FLUID LIST GRID */}
      <div className="flex-grow overflow-y-auto pr-2 custom-scrollbar grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
        {citizens.map(c => (
          <div 
            key={c.id}
            onClick={() => setSelectedCitizen(c)}
            className="bg-white border-4 border-[#47510B] p-6 rounded-[40px] shadow-[6px_6px_0_0_#47510B] hover:translate-x-1 hover:-translate-y-1 hover:shadow-[10px_10px_0_0_#CAD23C] transition-all cursor-pointer flex items-center justify-between group"
          >
            <div className="min-w-0">
              <p className="text-[10px] text-[#CAD23C] mb-1">{c.id}</p>
              <h3 className="text-2xl truncate">{c.name}</h3>
              <div className="flex gap-3 mt-2">
                <span className="text-[10px] bg-[#47510B]/5 px-2 py-0.5 rounded italic">{c.area}</span>
                <span className={`text-[10px] px-2 py-0.5 rounded ${c.status === 'ACTIVE' ? 'bg-[#CAD23C]' : 'bg-[#AB1717] text-white'}`}>{c.status}</span>
              </div>
            </div>
            <ChevronRight className="opacity-20 group-hover:opacity-100 group-hover:translate-x-2 transition-all" size={32} />
          </div>
        ))}
      </div>

      {/* 🏗️ DOSSIER MODAL (The Flexible Engine) */}
      {selectedCitizen && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4 md:p-8 lg:p-12">
          {/* Backdrop */}
          <div className="absolute inset-0 bg-[#47510B]/90 backdrop-blur-md animate-in fade-in duration-300" onClick={closeModal} />

          {/* Container: Flexible Width/Height */}
          <div className="relative w-full max-w-6xl h-full max-h-[90vh] bg-white border-[8px] border-[#47510B] rounded-[60px] shadow-[20px_20px_0_0_#000] overflow-hidden flex flex-col animate-in zoom-in-95 duration-200">

            {/* MODAL HEADER */}
            <div className="bg-[#47510B] p-8 text-white flex justify-between items-start shrink-0">
              <div className="flex gap-6 items-center">
                <div className="w-20 h-20 bg-[#FFF24D] rounded-3xl flex items-center justify-center text-[#47510B]">
                  <User size={48} strokeWidth={3} />
                </div>
                <div>
                  <h2 className="text-4xl md:text-6xl leading-none">{selectedCitizen.name}</h2>
                  <div className="flex gap-4 mt-2">
                    <span className="bg-white/10 px-3 py-1 rounded-lg text-xs font-black">ID: {selectedCitizen.id}</span>
                    <span className="bg-[#CAD23C] text-[#47510B] px-3 py-1 rounded-lg text-xs font-black">{selectedCitizen.status}</span>
                  </div>
                </div>
              </div>
              <button onClick={closeModal} className="bg-white/10 hover:bg-[#AB1717] p-4 rounded-2xl transition-all">
                <X size={32} />
              </button>
            </div>

            {/* FLEXIBLE FILTER HUD */}
            <div className="bg-[#FDFAD8] border-b-4 border-[#47510B] p-4 flex gap-3 overflow-x-auto no-scrollbar shrink-0">
              {[
                { id: 'PROFILE', label: 'CORE_PROFILE', icon: <User size={16}/> },
                { id: 'REPORTS', label: 'INCIDENT_HISTORY', icon: <FileText size={16}/> },
                { id: 'PENALTIES', label: 'INFRACTIONS', icon: <AlertOctagon size={16}/> },
                { id: 'SCHEDULES', label: 'LOGISTICS', icon: <Calendar size={16}/> },
                { id: 'SUBS', label: 'BILLING_RIG', icon: <CreditCard size={16}/> }
              ].map(f => (
                <button 
                  key={f.id}
                  onClick={() => setActiveFilter(f.id)}
                  className={`flex items-center gap-3 px-6 py-3 rounded-2xl text-xs font-black border-4 transition-all whitespace-nowrap ${activeFilter === f.id ? 'bg-[#47510B] text-white border-[#47510B]' : 'bg-white border-[#47510B] hover:bg-[#FFF24D]'}`}
                >
                  {f.icon} {f.label}
                </button>
              ))}
            </div>

            {/* MODAL CONTENT: SCROLLABLE & FLEXIBLE */}
            <div className="flex-grow p-10 overflow-y-auto custom-scrollbar">

              {activeFilter === 'PROFILE' && (
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 animate-in slide-in-from-right-8 duration-300">
                  <div className="space-y-8">
                    <div className="group">
                      <label className="text-xs opacity-40 block mb-2 underline decoration-[#CAD23C] decoration-4">REGISTERED_ADDRESS</label>
                      <p className="text-3xl leading-tight">402, ROYAL RESIDENCY, GANDHI NAGAR, HYDERABAD, 500080</p>
                    </div>
                    <div className="grid grid-cols-2 gap-6">
                      <div className="bg-[#F3F4F6] p-4 rounded-2xl border-2 border-[#47510B]">
                        <label className="text-[10px] opacity-40">CONTACT_COMM</label>
                        <p className="text-xl flex items-center gap-2 mt-1"><Phone size={16}/> {selectedCitizen.phone}</p>
                      </div>
                      <div className="bg-[#F3F4F6] p-4 rounded-2xl border-2 border-[#47510B]">
                        <label className="text-[10px] opacity-40">GEO_ASSIGNMENT</label>
                        <p className="text-xl flex items-center gap-2 mt-1"><MapPin size={16}/> {selectedCitizen.zone}</p>
                      </div>
                    </div>
                  </div>
                  <div className="bg-[#47510B] text-[#FFF24D] rounded-[40px] p-8 flex flex-col justify-center items-center text-center shadow-[15px_15px_0_0_#CAD23C]">
                    <Trophy size={64} className="mb-6 animate-bounce" />
                    <h3 className="text-4xl">ELITE_CITIZEN</h3>
                    <p className="mt-2 opacity-60">TOP 5% IN RECYCLING ACCURACY</p>
                    <div className="mt-8 w-full bg-white/10 h-4 rounded-full overflow-hidden">
                        <div className="bg-[#CAD23C] h-full w-[85%]" />
                    </div>
                    <p className="text-[10px] mt-2 italic">850/1000 POINTS TO NEXT TIER</p>
                  </div>
                </div>
              )}

              {activeFilter === 'REPORTS' && (
                <div className="space-y-4 animate-in slide-in-from-right-8">
                   <div className="flex justify-between items-center mb-6">
                      <h3 className="text-3xl">LATEST_REPORTS</h3>
                      <button className="bg-[#47510B] text-white px-4 py-2 rounded-xl text-[10px]">+ FILE_NEW</button>
                   </div>
                   {[1, 2, 3].map(i => (
                     <div key={i} className="border-4 border-[#47510B] p-6 rounded-[32px] flex justify-between items-center hover:bg-[#F3F4F6] transition-colors">
                        <div>
                           <p className="text-2xl">MISSED_COLLECTION_LOG_{i}</p>
                           <p className="text-xs opacity-40">REF: #REP-00{i} // 22_MAR_2026</p>
                        </div>
                        <CheckCircle2 className="text-[#CAD23C]" size={32} />
                     </div>
                   ))}
                </div>
              )}

              {/* Logic for Penalties, Schedules, Subs goes here... */}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CitizensTab;
